  use_canvas(64);
  GC gc = wide_gc(4, CapButt, JoinBevel);
  const XPoint path[] = {{10, 30}, {30, 30}, {30, 10}};
  draw_path(gc, path, 3);
  TEST_ASSERT_EQUAL_HEX16(0xFFFF, at(30, 30));
  TEST_ASSERT_EQUAL_HEX16(0, at(31, 31));
  XFreeGC(dpy, gc);
}

