static void join_at(Canvas *c, int ix, int iy, vec2 d1, vec2 d2, int w,
                    int style, uint16_t colour) {
  const float dot = d1.x * d2.x + d1.y * d2.y;
  const float cross = d1.x * d2.y - d1.y * d2.x;
