  const float side = cross > 0 ? -1.0f : 1.0f;
  const vec2 n1 = {-d1.y * side, d1.x * side}, n2 = {-d2.y * side, d2.x * side};
  const vec2 p1 = {v.x + n1.x * half, v.y + n1.y * half};
