  XFreeGC(dpy, gc);
  XFreePixmap(dpy, src);
  XFreePixmap(dpy, mask);
  XFreePixmap(dpy, dst);
}

void test_copy_area_with_a_clip_mask_skips_masked_pixels(void) {
  Pixmap mask = None;
